import ballerina/io;

// Aggregates responses from multiple API endpoints, categorizes them by status
// and flags, and processes mixed result types.
type ApiResponse record {|
    string endpoint;
    int status;
    int flags;
    any result;
|};

public function main() {
    // Response flags
    int cached = 1 << 0;
    int partial = 1 << 1;
    int paginated = 1 << 2;

    map<string> statusDesc = {"200": "OK", "206": "Partial"}; // status descriptions

    ApiResponse res1 = {endpoint: "/users", status: 200, flags: cached, result: 150};
    ApiResponse res2 = {endpoint: "/orders", status: 200, flags: cached + paginated, result: "paginated"};
    ApiResponse res3 = {endpoint: "/products", status: 206, flags: partial, result: 42};
    ApiResponse[] responses = [res1, res2, res3];
    [string, int] healthCheck = ["/health", 200];

    io:println("Health Check: ", healthCheck[0], " (", healthCheck[1], ")");
    io:println("\nAPI Responses: ", responses.length());
    io:println("------------------");

    foreach ApiResponse res in responses {
        io:println("\nEndpoint: ", res.endpoint);
        if res.status == 200 {
            io:println("  Status: ", res.status, " ", statusDesc["200"]);
        }
        if res.status == 206 {
            io:println("  Status: ", res.status, " ", statusDesc["206"]);
        }

        if res.flags >= paginated {
            io:println("  [Paginated]");
        }
        if res.flags == cached {
            io:println("  [Cached]");
        }
        if res.flags == partial {
            io:println("  [Partial]");
        }

        any result = res.result;
        if result is int {
            int count = <int>result;
            io:println("  Count: ", count);
            if count > 100 {
                io:println("  Volume: High");
            } else {
                io:println("  Volume: Normal");
            }
        }
        if result is string {
            io:println("  Info: ", result);
        }
    }
}

import ballerina/io;

public function main() {
    int n = 10;
    int i = 0;
    while (i < n) {
        io:println("F(", i, ") = ", fibonacci(i));
        i += 1;
    }
}

function fibonacci(int n) returns int {
    if (n <= 1) {
        return n;
    }
    int prev = 0;
    int curr = 1;
    int i = 2;
    while (i <= n) {
        int next = prev + curr;
        prev = curr;
        curr = next;
        i += 1;
    }
    return curr;
}

import ballerina/io;

// Shows the delivery schedule of pending orders
type Order record {|
    string id;
    string customer;
    int amount;
    int areaCode;
|};

public function main() {
    Order order1 = {id: "ORD001", customer: "Alice", amount: 150, areaCode: 1};
    Order order2 = {id: "ORD002", customer: "Bob", amount: 75, areaCode: 2};
    Order order3 = {id: "ORD003", customer: "Carol", amount: 200, areaCode: 1};

    Order[] orders = [order1, order2, order3];
    map<int> deliveryFee = {"Downtown": 5, "Suburb": 10};

    io:println("=== Delivery Schedule ===");
    foreach int code in 1 ... 2 {
        if code == 1 {
            io:println("\nDowntown (fee: $", deliveryFee["Downtown"], ")");
        }
        if code == 2 {
            io:println("\nSuburb (fee: $", deliveryFee["Suburb"], ")");
        }
        foreach Order ord in orders {
            if ord.areaCode == code {
                io:println("  ", ord.id, " | ", ord.customer, " | $", ord.amount);
            }
        }
    }
}
